package com.termux.app.workspace;
import org.junit.*;import static org.junit.Assert.*;import org.json.*;import java.util.*;
@org.junit.runner.RunWith(org.robolectric.RobolectricTestRunner.class) @org.robolectric.annotation.Config(sdk=28,application=android.app.Application.class)
public class ChatFileReferencesTest {
 JSONObject row(String key,String message,String kind,String body)throws Exception{return new JSONObject().put("key",key).put("message",message).put("kind",kind).put("body",body);}
 @Test public void explicitFileLinksAndMissingUploadsOnlyWithStableMessageOwnership()throws Exception{String id="0123456789abcdef0123456789abcdef";JSONObject user=row("u","user","user","[TermuxJobs attachment:"+id+"]\nName: missing.zip\nFile: /tmp/chat-attachments/"+id+"/original.zip\nSize: 123 bytes.\n").put("messageTime","2026-11-05T10:00:00Z");JSONObject agent=row("a","agent","text","[file](</project/long name.stl>) [web](https://example.org/index.html) bare /project/not-a-link.txt");List<ChatFileReferences.Entry> list=ChatFileReferences.collect(Arrays.asList(user,agent));assertEquals(2,list.size());assertEquals("user",list.get(0).sender);assertEquals(1793872800000L,list.get(0).time);assertEquals("agent",list.get(1).sender);assertEquals(0,list.get(1).time);assertEquals("/project/long name.stl",list.get(1).file.getString("path"));assertEquals("a",list.get(1).key);assertTrue(ChatFileReferences.collect(Collections.emptyList()).isEmpty());}
 @Test public void nativeCardAndLinkAreDeduplicatedPerMessageNotAcrossMessages()throws Exception{JSONObject a=row("a","m","text","[file](/fake/x.log)");JSONObject b=row("b","m","attachment","").put("attachment",new JSONObject().put("path","/fake/x.log").put("name","x.log"));JSONObject c=row("c","other","text","[file](/fake/x.log)");assertEquals(2,ChatFileReferences.collect(Arrays.asList(a,b,c)).size());}
 @Test public void directRemoteFilesAreRecordsWithoutRequestsAndOrdinaryWebPagesAreNot()throws Exception{JSONObject r=row("r","m","text","[archive](https://example.invalid/data.zip) [website](https://example.invalid/index.html) [code](https://github.com/u/r/blob/main/a.txt)");List<ChatFileReferences.Entry> list=ChatFileReferences.collect(Arrays.asList(r));assertEquals(1,list.size());assertTrue(list.get(0).file.getString("path").startsWith("https://"));}
 @Test public void noFileReadAndNoInventedDatesForUnknownNativeFields()throws Exception{JSONObject r=row("x","y","text","[missing](/impossible/fake.blend)").put("eventTime",1234567);ChatFileReferences.Entry e=ChatFileReferences.collect(Arrays.asList(r)).get(0);assertEquals(0,e.time);assertEquals("fake.blend",e.file.getString("name"));}
}
